(457, 473, 53, NULL, 2, 'UNIT', 'Epson', 'L18050', '<p>6-color dye-based inks (Black, Cyan, Magenta, Yellow, Light Cyan, Light Magenta)</p><p>5760 x 1440 dpi</p><p>Up to A3+ (Borderless)</p><p>• <strong>ISO (A4):</strong> 8.0 ipm (Black/Color)</p><p>• <strong>Photo Default (4x6\"):</strong> ~27 seconds per photo</p><p>• <strong>Draft (A4):</strong> Up to 22 ppm</p><p>Wi-Fi, Wi-Fi Direct, USB 2.0</p><p>Wireless printer</p><p>Minimum 100 sheets input capacity</p>', 30495, NULL, 544.55, NULL, 0, 0, 0, NULL, NULL, '2026-07-02 09:35:38'),
