(491, 473, 47, NULL, 2, 'UNIT', 'EPSON', 'L18050', '<p>6-color dye-based inks (Black, Cyan, Magenta, Yellow, Light Cyan, Light Magenta)</p><p>5760 x 1440 dpi</p><p>Up to A3+ (Borderless)</p><p>• <strong style=\"background-color: transparent;\">ISO (A4):</strong> 8.0 ipm (Black/Color)</p><p>• <strong style=\"background-color: transparent;\">Photo Default (4x6\"):</strong> ~27 seconds per photo</p><p>• <strong style=\"background-color: transparent;\">Draft (A4):</strong> Up to 22 ppm</p><p>Wi-Fi, Wi-Fi Direct, USB 2.0</p><p>Wireless printer</p><p>Minimum 100 sheets input capacity</p><p>Warranty 2years or 50,000 pages, whichever comes first</p>', 27405, NULL, 489.38, NULL, 0, 0, 1, NULL, NULL, '2026-08-03 16:12:21'),
(492, 475, 47, NULL, 3, 'UNIT', 'EPSON', 'L121', '<p><strong>General:</strong></p><p>Type: Ink Tank Printer</p><p>Condition: Brand new, factory-sealed, and unused</p><p><strong>Printing</strong></p><p>Supported Paper Sizes: A4, Letter, Legal</p><p>Print Resolution: At least 720 x 720 dpi</p><p>Minimum Standard paper input capacity of 50 sheets Plain Paper (70 g/m2)</p><p><strong>Connectivity</strong></p><p>USB interface</p><p>Ink System</p><p>Must use a refillable ink tank system</p><p><strong>Inclusions</strong></p><p>Initial set of ink bottles supplied with the unit</p><p>1 additional set of ink bottles</p><p><strong>Warranty and Support</strong></p><p>Must be covered by a minimum one (1) year warranty on parts and service</p>', 5057, NULL, 135.46, NULL, 0, 0, 1, NULL, NULL, '2026-08-03 16:16:55'),
(493, 474, 47, NULL, 2, 'UNIT', 'EPSON', 'L3350', '<p><strong>General:</strong></p><p>Type: Ink Tank Multifunction Printer with Scanner</p><p>Condition: Brand new, factory-sealed, and unused</p><p><strong>Printing</strong></p><p>Supported Paper Sizes: A4, A5, A6, Letter, Legal</p><p>Print Resolution: At least 5760 x 1440 dpi</p><p>Minimum Standard paper input capacity of 50 sheets Plain Paper (70 g/m2)</p><p><strong>Scanning</strong></p><p>Maximum Scan Size: A4</p><p><strong>Connectivity</strong></p><p>With built-in Wi-Fi capability</p><p>Must support network printing</p><p><strong>Ink System</strong></p><p>Must use a reliable tank system</p><p><strong>Inclusions</strong></p><p>Initial set of ink bottles supplied with the unit</p><p>1 additional set of ink bottles</p><p><strong>Warranty and Support</strong></p><p>Must be covered by a minimum one (1) year warranty on parts and service</p>', 9685, NULL, 172.95, NULL, 0, 0, 1, NULL, NULL, '2026-08-05 09:28:28'),
(494, 474, 47, 9, 1, 'UNIT', 'EPSON', 'L3350', '<p><strong>General:</strong></p><p>Type: Ink Tank Multifunction Printer with Scanner</p><p>Condition: Brand new, factory-sealed, and unused</p><p><strong>Printing</strong></p><p>Supported Paper Sizes: A4, A5, A6, Letter, Legal</p><p>Print Resolution: At least 5760 x 1440 dpi</p><p>Minimum Standard paper input capacity of 50 sheets Plain Paper (70 g/m2)</p><p><strong>Scanning</strong></p><p>Maximum Scan Size: A4</p><p><strong>Connectivity</strong></p><p>With built-in Wi-Fi capability</p><p>Must support network printing</p><p><strong>Ink System</strong></p><p>Must use a reliable tank system</p><p><strong>Inclusions</strong></p><p>Initial set of ink bottles supplied with the unit</p><p>1 additional set of ink bottles</p><p><strong>Warranty and Support</strong></p><p>Must be covered by a minimum one (1) year warranty on parts and service</p>', 9685, NULL, 86.47, NULL, 1, 0, 0, NULL, NULL, '2026-08-05 09:32:51'),
(495, 502, 76, NULL, 4, 'Unit', 'ACER', 'Predator Helios Neo 16 PHN16-I31-758F OPI', '<p>Preferred Brand: <strong>ACER PREDATOR HELIOS NEO 16</strong>,</p><p><br></p><p>16\" Display</p><p><br></p><p>• Intel® Core™ i7-HX processor (30 MB Smart Cache, 2.2 GHz Performance-core with Intel® Turbo Boost Max Technology 3.0 up to 5.1 GHz, overclock capable), supporting hybrid core architecture with Performance-core and Efficient-core</p><p><br></p><p>• 1×16GB of DDR5 5600MHz system memory, upgradable to 64GB using two soDIMM modules, 1×512GB NVMe SSD supporting 180 Hz</p><p><br></p><p>• NVIDIA® GeForce RTX™ 5050 with VRAM of 8GB, supporting 2560 NVIDIA CUDA® Cores.</p><p><br></p><p>• USB Type-C™ port supporting: DisplayPort 2.1 over USB-C via dGPU, Thunderbolt™ 4, USB charging 5 V; 3 A, DC-in port 20 V; 100 W</p><p><br></p><p>• HDMI® 2.1 port with HDCP support</p><p><br></p><p>• Keyboard: 103(US)/104(Uk)/107 (JP) key, FineTip RGB-backlight keyboard with independent standard numeric keypad and international language support</p><p><br></p><p>• Microsoft Precision Touchpad certification</p>', 151060, NULL, 5395, NULL, 0, 0, 0, NULL, NULL, '2026-08-24 10:08:15'),
