(616, 606, 27, 8, 1, 'unit', 'ACASIS', '10Gbps M.2 NVMe SSD Enclosure USB C Magnetic Docking Station with Cooling Fan', '<p>Specification: Speed: 10Gbps (USB C 3.2 Gen2) SSD: M.2 NVMe M/B+M key; 2230/2242/2260/2280; up to 8TB Features: Magnetic, built in cooling fan, tool free Material: Aluminum alloy OS: Windows/macOS/Linux/Android</p>', 1890, NULL, 16.88, NULL, 0, 1, 0, NULL, NULL, '2026-10-09 15:16:16'),
(617, 607, 19, 31, 1, 'unit', 'NEEWER', 'PS015 Foldable V Mount Battery Plate with Arca Type Camera Baseplate', '<p>Specification: Type: V mount battery plate + Arca quick release base Material: Aluminum alloy Adjust: 180° tilt, extendable 36.5mm Mounts: Dual Arca type, 1/4\" &amp; 3/8\" threads Weight: 249g Use: Add V mount power to cameras/rigs/gimbals</p>', 3680, NULL, 32.86, NULL, 0, 1, 0, NULL, NULL, '2026-10-09 15:16:43'),
