(619, 609, 19, 31, 1, 'unit', 'DJI Mic 3', '(2 TX + 1 RX + Charging Case)', '<p>Specification: Type: 2 person digital wireless mic system Pattern: Omnidirectional Range: Up to 250 m line of sight Recording: Dual file 32 bit float internal recording Battery: ~6 h per TX; ~5.5 h RX; total ~28 h with case Weight: TX ~16 g; RX ~27 g Output: 3.5 mm + USB C; built in timecode &amp; noise cancel</p>', 15890, NULL, 141.88, NULL, 0, 1, 0, NULL, NULL, '2026-10-09 15:18:14'),
