(634, 617, 27, 8, 1, 'Unit', 'TP-Link', 'ER605 Dual WAN Router', '<ul><li>5 Gigabit ports total (1 dedicated Gigabit WAN port, 2 dedicated Gigabit LAN ports, and 2 interchangeable Gigabit WAN/LAN ports)</li><li>USB Port: 1 USB 2.0 port supporting 3G/4G/LTE USB dongles for backup WAN connection</li><li>Multi-WAN: Supports up to 3 Ethernet WAN ports plus 1 USB mobile broadband WAN link with load balancing</li><li>VPN Protocols: IPSec, OpenVPN, PPTP, and L2TPConcurrent</li><li>VPN Tunnels: Up to 20 IPSec, 16 L2TP, 16 PPTP, and 16 OpenVPN tunnels Management: Integrated with Omada Software Defined Networking (SDN) platform for centralized cloud management, app control, and standalone</li><li>Web UI Security: SPI firewall, DoS defense, IP/MAC/URL filtering, and 4 kV lightning protection.</li></ul>', 2795, NULL, 24.96, NULL, 0, 1, 1, NULL, NULL, '2026-10-16 10:17:55'),
(635, 618, 27, 8, 4, 'Boxes', 'BELDEN', 'CABLE UTP  CAT6 BELDEN 7814A', '<ul><li>CAT 6 4PR × 24AWG, Solid Bare Copper Conductor, U/UTP, PE Insulation, CM, PVC Jacket, Indoor</li></ul>', 10290, NULL, 367.5, NULL, 0, 1, 1, NULL, NULL, '2026-10-16 10:19:03'),
