(638, 622, 27, 8, 2, 'Units', 'TP-Link', 'TP-Link Archer AX55', '<ul><li>Standards and Protocols: Wi-Fi 6 IEEE 802.11ax/ac/a/h/a 5 GHz / IEEE 802.11ax/n/b/g 2.4 GHz</li><li>WiFi Speeds: AX3000 5 GHz: 2402 Mbps (802.11ax, HE160)/ 2.4 GHz: 574 Mbps (802.11ax)</li></ul>', 3895, NULL, 69.55, NULL, 0, 1, 1, NULL, NULL, '2026-10-16 10:24:05'),
