(641, 626, 27, 8, 9, 'Units', 'Mercusys', 'MS108GS 8-Port Gigabit Network Switch', '<ul><li>-Interfaces: 8×10/100/1000Mbps Ports, Auto-Negotiation, Auto-MDI/MDIX</li><li>External Power Supply: 5V/0.6A</li><li>Standards and Protocols: IEEE 802.3, IEEE 802.3u, IEEE 802.3x CSMA/CD</li><li>Data Rates: 10/100/1000Mbps at Half Duplex / 20/200/2000Mbps at Full Duplex</li></ul>', 850, NULL, 68.3, NULL, 0, 1, 1, NULL, NULL, '2026-10-16 10:26:17'),
(642, 619, 27, 8, 1, 'Roll', 'Comlink', 'C1.0 Drop Cable 2F(1KM) 1.0mm, GJYXCH G.657A1 Anti-Bending 2Core 3 Steel Galvanized', '<ul><li>Outdoor Leather Optical Fiber Drop Cable, 2 Core</li><li>Cable length: 1km / 1000M</li><li>Color: Pure black</li><li>Optical fiber insertion removal times</li><li>1000 times reinforcement material</li></ul><p>Reinforced phosphating steel wire.</p><p>39.8x33.4x39.8CM Used for networking / ethetnet cabling</p>', 2950, NULL, 26.34, NULL, 0, 1, 1, NULL, NULL, '2026-10-16 10:29:02'),
