(718, 631, 47, 9, 5, 'Units', 'WACOM', 'STU-430 LCD Signature Pad', '<p>&nbsp;<strong><u>WACOM STU-430 LCD Signature Pad</u></strong></p><p><br></p><ul><li>4.5” monochrome, reflective LCD display easily accommodates large signatures and soft buttons</li><li>Patented cordless, battery-free pen with 1024 levels of pressure sensitivity to accurately capture the unique pen pressure profile of a signature to be included in the biometric data</li><li>State-of-the-art RSA/AES encryption to perform secure transactions</li><li>Pen holder/USB cable lock combination provides a convenient area to place the pen, plus USB lock prevents accidental disconnection of USB cable</li><li>Unique hardware ID so the exact device used for signing can be identified</li></ul>', 11000, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, '2026-10-22 16:43:07'),
