(473, 70, 1, 2, 'UNIT', 'A3+ Ink Tank Printer with Wifi', '<p><strong>General:</strong></p><p>Type: Ink Tank Printer</p><p>Condition: Brand new, factory-sealed, and unused</p><p><strong>Printing</strong></p><p>Supported Paper Sizes: A3+, A3, USB, 11 x 14\", Legal, A4, Letter, 8 x 10\", 5 x 7\", 4 x 6\", 3.5 x 5\"</p><p>Print Resolution: At least 5760 x 1440 dpi</p><p>Minimum Standard paper input capacity of 100 sheets Plain Paper (70 g/m2)</p><p><strong>Connectivity</strong></p><p>With built-in Wi-Fi capability</p><p>Must support network printing</p><p><strong>Ink System</strong></p><p>Must use a reliable tank system</p><p><strong>Inclusions</strong></p><p>Initial set of ink bottles supplied with the unit</p><p>1 additional set of ink bottles</p><p><strong>Warranty and Support</strong></p><p>Must be covered by a minimum one (1) year warranty on parts and service</p>', 0),
(474, 70, 2, 2, 'UNIT', 'A4 Ink Tank Multifunction Printer with Scanner', '<p><strong>General:</strong></p><p>Type: Ink Tank Multifunction Printer with Scanner</p><p>Condition: Brand new, factory-sealed, and unused</p><p><strong>Printing</strong></p><p>Supported Paper Sizes: A4, A5, A6, Letter, Legal</p><p>Print Resolution: At least 5760 x 1440 dpi</p><p>Minimum Standard paper input capacity of 50 sheets Plain Paper (70 g/m2)</p><p><strong>Scanning</strong></p><p>Maximum Scan Size: A4</p><p><strong>Connectivity</strong></p><p>With built-in Wi-Fi capability</p><p>Must support network printing</p><p><strong>Ink System</strong></p><p>Must use a reliable tank system</p><p><strong>Inclusions</strong></p><p>Initial set of ink bottles supplied with the unit</p><p>1 additional set of ink bottles</p><p><strong>Warranty and Support</strong></p><p>Must be covered by a minimum one (1) year warranty on parts and service</p>', 0),
(475, 70, 3, 3, 'UNIT', 'A4 Ink Tank Printer', '<p><strong>General:</strong></p><p>Type: Ink Tank Printer</p><p>Condition: Brand new, factory-sealed, and unused</p><p><strong>Printing</strong></p><p>Supported Paper Sizes: A4, Letter, Legal</p><p>Print Resolution: At least 720 x 720 dpi</p><p>Minimum Standard paper input capacity of 50 sheets Plain Paper (70 g/m2)</p><p><strong>Connectivity</strong></p><p>USB interface</p><p>Ink System</p><p>Must use a refillable ink tank system</p><p><strong>Inclusions</strong></p><p>Initial set of ink bottles supplied with the unit</p><p>1 additional set of ink bottles</p><p><strong>Warranty and Support</strong></p><p>Must be covered by a minimum one (1) year warranty on parts and service</p>', 0),
