(617, 97, 1, 1, 'Unit', 'Dual WAN Router Ethernet Port', '<ul><li>5 Gigabit ports total (1 dedicated Gigabit WAN port, 2 dedicated Gigabit LAN ports, and 2 interchangeable Gigabit WAN/LAN ports)</li><li>USB Port: 1 USB 2.0 port supporting 3G/4G/LTE USB dongles for backup WAN connection</li><li>Multi-WAN: Supports up to 3 Ethernet WAN ports plus 1 USB mobile broadband WAN link with load balancing</li><li>VPN Protocols: IPSec, OpenVPN, PPTP, and L2TPConcurrent</li><li>VPN Tunnels: Up to 20 IPSec, 16 L2TP, 16 PPTP, and 16 OpenVPN tunnels Management: Integrated with Omada Software Defined Networking (SDN) platform for centralized cloud management, app control, and standalone</li><li>Web UI Security: SPI firewall, DoS defense, IP/MAC/URL filtering, and 4 kV lightning protection.</li></ul><p><br></p>', 4133),
