(624, 97, 8, 1, 'Unit', 'Lightning-Fast - AX6000 8-Stream Wi-Fi 6 Router with 2.5G Multi-Gigabit Port VPN', '<ul><li>Standards and Protocols: -Wi-Fi 6 IEEE 802.11ax/ac/a/n/a 5 GHz / IEEE 802.11ax/n/b/g 2.4 GHz WiFi Speeds: AX6000 5 GHz: 4804Mbps (802.11ax, HE160) / 2.4 GHz: 1148 Mbps (802.11ax)</li></ul>', 14486),
(625, 97, 9, 1, 'Unit', '24-Port Gigabit Network Switch', '<ul><li>Interfaces: 24×10/100/1000Mbps RJ45 Ports, Auto-Negotiation, Auto MDI/MDIX </li><li>External Power Supply: 100-240VAC, 50/60Hz </li><li>Standards and Protocols: IEEE 802.3i, IEEE 802.3u, IEEE 802.3ab, IEEE 802.3x, IEEE 802.1p</li></ul>', 4771),
(626, 97, 10, 9, 'Units', '8 Port Gigabit Network Switch', '<ul><li>-Interfaces: 8×10/100/1000Mbps Ports, Auto-Negotiation, Auto-MDI/MDIX </li><li>External Power Supply: 5V/0.6A </li><li>Standards and Protocols: IEEE 802.3, IEEE 802.3u, IEEE 802.3x CSMA/CD </li><li>Data Rates: 10/100/1000Mbps at Half Duplex / 20/200/2000Mbps at Full Duplex</li></ul>', 11619),
(627, 98, 1, 2, 'Unit', 'Hard Disk Drive', '<p>HD SATA&nbsp;4TB SEAGATE SKYHAWK 3.5\" ST4000VX016</p>', 29552),
(628, 100, 1, 10, 'Sets', 'Computer Set', '<p><strong>PROCESSOR (CPU)</strong></p><ol><li>Intel Core i5 - 14th Generation   </li><li>10 Cores (6 Performance + 4 Efficient)   </li><li>Base Frequency -2.5 GHz   </li><li>18MB Cache   </li><li>IntelUHD Graphics (Integrated)   </li></ol><ul><li><strong>MEMORY (RAM)</strong>   </li></ul><ol><li>16GB DDR4 RAM   </li><li>Speed:3200 MHz (Expandable up to 32GB)   STORAGE   </li><li>Primary Drive (System: 480 GB SSD   (SATA or NVMe, recommended NVMe for faster performance)   </li><li>Secondary Storage: 1TB HDD, 7200 RPM   MOTHERBOARD   </li><li>LGA 1700   </li><li>DDR4 support   </li><li>M.2 slot for NVMe ssd, usb 3.2 ports   </li><li>HDMI / Display Port Output   </li></ol><ul><li><strong>POWER SUPPLY </strong>  </li></ul><ol><li>700W PSU  </li><li> 80+ Certified (Recommended)   </li></ol><ul><li><strong>CABINET /&nbsp;CASE   </strong></li></ul><ol><li>Mid Tower Cabinet   </li><li>Front USB Ports   </li><li>Good Airflow Design   </li></ol><ul><li><strong>OPERATING SYSTEM</strong>   </li></ul><ol><li>Windows 11 Pro   </li></ol><ul><li><strong>ADD-ONS</strong>  </li></ul><ol><li> Keyboard &amp; Mouse, Monitor (24\'\' LED)   </li><li>UPS: 650 VA </li></ol>', 752910),
(629, 100, 2, 4, 'Units', 'Scanner', '<ul><li>Scanning speed of up to 40 ppm / 80 ipm</li><li>Automatic Document Feeder (ADF) of up to 60 sheets</li><li>Daily duty cycle of up to 6,500 sheets</li><li>One-pass duplex scanning</li><li>Paper protection function and image sensor glass dirt detection</li></ul>', 166752),
(630, 100, 3, 6, 'Units', 'Print, Scan, Copy, Fax with ADF', '<p><br></p><ul><li>Compact EcoTank Design with accessible ink tank body</li><li>Print speeds up to 18 ipm for black and 9 ipm for colour</li><li>Auto-Duplex Print, Scan, Copy</li><li>Borderless Printing up to A4 size</li><li>Ethernet, Wi-Fi &amp; Wi-Fi Direct</li></ul>', 154122),
(631, 100, 4, 5, 'Units', 'Digital signature pad', '<ul><li>4.5” monochrome, reflective LCD display easily accommodates large signatures and soft buttons</li><li>Patented cordless, battery-free pen with 1024 levels of pressure sensitivity to accurately capture the unique pen pressure profile of a signature to be included in the biometric data</li><li>State-of-the-art RSA/AES encryption to perform secure transactions</li><li>Pen holder/USB cable lock combination provides a convenient area to place the pen, plus USB lock prevents accidental disconnection of USB cable</li><li>Unique hardware ID so the exact device used for signing can be identified</li></ul>', 89900),
(632, 100, 5, 2, 'Units', '4TB 3.5 Hard Disk Drive', '<ul><li>Factor: 3.5 -inch</li><li>&nbsp;Interface: SATA 6 Gb/s</li><li>Rotational Speed: 7200 RPM</li><li>Cache Memory: 256MBMax</li></ul>', 40600),
(633, 100, 6, 8, 'Unit', 'Laptop Computer', '<p>Processor: Intel Core i7-13620H</p>', 649542),
(634, 101, 1, 4, 'units', 'Two-Door Refrigerator Inverter Technology', '7.3 cubic foot', 95988),
(635, 101, 2, 4, 'units', 'Microwave Oven', '23L Tact Control w/LED Display', 33872),
(636, 101, 3, 10, 'units', 'Hospital Hampers', 'Heavy Duty', 67500),
(637, 101, 4, 1, 'unit', 'Hand Pallet Truck 3000kg', '3000kg', 40433),
(638, 99, 1, 4, 'units', 'Rechargeable lithium battery set', 'including 8pcs 1.5v aa batteries and multi function charging case', 0),
(639, 99, 2, 6, 'units', '120w gallium nitride type c fast charger', '120w', 0),
(640, 99, 3, 10, 'units', 'Universal tower extension cord 12 gang with switch', '12 gang', 0),
(641, 103, 1, 10, 'Unit', 'Printer', '<p>Type: Single-function ink tank printer (Print only) </p><p>Print Resolution: Up to 720 x 720 dpi </p><p>Print Speed: 9.0 ipm (Black), 4.8 ipm (Color)Ink Yield: 4,500 pages (Black), 7,500 pages (Color) Paper Capacity: 50 sheets Paper Size: Up to 8.5\" x 44\" (A4, Letter, Legal, Custom) </p><p>Connectivity: USB 2.0 </p><p>Dimensions: 461 x 215 x 130 mm Weight: 2.4 kg </p><p>Features: Compact design, high-yield refillable ink tank, borderless photo printing up to 4R.</p>', 79680),
(642, 104, 1, 100, 'pcs', 'Wallfan', 'n/a', 0),
